  ('752f684b-e80e-50ec-bd2e-830949ff8cb8'::uuid, 'a07593d8-957d-4a85-9672-f3fabf576fd5', 'Amanda Grayson, Logic''s Link', 'https://cards.scryfall.io/normal/front/a/0/a07593d8-957d-4a85-9672-f3fabf576fd5.jpg', '{3}{G}', 'Legendary Creature — Human Advisor', ARRAY['G']::text[], ARRAY['G']::text[], 'Affinity for Vulcans (This spell costs {1} less to cast for each Vulcan you control.)
