  '82438815-e711-5f11-9ccd-6b8ad1c69b4c'::uuid, null, 'Landing Party Collector''s Edition', 'commander', 'Landing Party Collector''s Edition is an official Commander precon from TRC, released 2026-11-13.', 'public', true, true,
